// Valida y normaliza el input. Espera:
// {
//   "message": "texto del cliente",
//   "history": [{ role: 'user'|'assistant', content: '...' }, ...] (opcional, max 10)
//   "contact_name": "opcional",
//   "contact_phone": "opcional",
//   "conversacion_id": numero opcional (de la tabla conversaciones, lo manda el Bridge)
// }

const body = $input.item.json.body || $input.item.json;
const message = (body.message || '').trim();
const history = Array.isArray(body.history) ? body.history.slice(-10) : [];
const contactName = body.contact_name || null;
const contactPhone = body.contact_phone || null;
const conversacionId = body.conversacion_id || null;

if (!message) {
  throw new Error('El campo "message" es obligatorio');
}

return {
  json: { message, history, contact_name: contactName, contact_phone: contactPhone, conversacion_id: conversacionId }
};

// Construye el contexto de la KB a inyectar en el system prompt
const ragResp = $input.item.json;
const input = $('Validar input').item.json;
const resultados = ragResp.resultados || [];

const relevantes = resultados.filter(r => r.similarity > 0.3);

let kbContext = '';
if (relevantes.length === 0) {
  kbContext = 'No se encontraron servicios relevantes en el catalogo para esta consulta. Si el cliente pregunta por un servicio especifico, escala a humano usando la funcion escalar_a_humano.';
} else {
  kbContext = 'SERVICIOS DEL CATALOGO RELEVANTES A LA CONSULTA (ordenados por relevancia):\n\n';
  relevantes.forEach((r, i) => {
    kbContext += `[${i + 1}] ${r.nombre} (slug: ${r.slug}, similarity: ${r.similarity.toFixed(2)})\n`;
    kbContext += `   - ${r.descripcion_corta}\n`;
    if (r.precio_setup) kbContext += `   - Precio setup: ${r.precio_setup}\n`;
    if (r.precio_recurrente) kbContext += `   - Precio recurrente: ${r.precio_recurrente}\n`;
    if (r.tiempo_entrega) kbContext += `   - Tiempo entrega: ${r.tiempo_entrega}\n`;
    if (r.entregables && r.entregables.length) {
      kbContext += `   - Entregables principales: ${r.entregables.slice(0, 3).join('; ')}\n`;
    }
    kbContext += '\n';
  });
}

return {
  json: {
    message: input.message,
    history: input.history,
    contact_name: input.contact_name,
    contact_phone: input.contact_phone,
    conversacion_id: input.conversacion_id,
    kb_context: kbContext,
    rag_results: relevantes
  }
};

// Construye payload completo para OpenAI con tools (function calling)
const input = $input.item.json;

const systemPrompt = `Sos el asistente de eXcalando, una agencia de capacidades digitales con IA en Colombia. Atendes WhatsApp de PyMEs (5-50 empleados, duenos 35-55 anos, no tecnicos).

IDENTIDAD
- Te presentas como "el asistente de eXcalando".
- Si preguntan "sos un bot?": "Si, soy un asistente IA del equipo. Detras hay personas reales que intervienen cuando hace falta. En que te puedo ayudar?"

PERSONALIDAD
- Profesional pero cercano. Tutea estricto (tu, NUNCA vos, NUNCA usted).
- Directo. Sin jerga inflada.
- Honesto. Si no sabes algo, lo decis y escalas.

FORMATO
- WhatsApp friendly. 3-4 lineas max por mensaje.
- Emojis con moderacion (1-2 max por respuesta).
- Saltos de linea para legibilidad.

OBJETIVO POR CONVERSACION (en este orden)
1. Entender que busca el cliente (1-2 preguntas)
2. Mostrarle el match con un servicio nuestro (1 mensaje)
3. Empujar al siguiente paso: Score Digital o agendar 30min
4. Si la conversacion se enfria, no insistir mas de 2 veces

QUE HACER (sin pedir permiso)
- Responder con base en los servicios del catalogo que te paso abajo
- Calificar (sector, tamano empresa, necesidad puntual)
- Mandar link al Score: https://excalando.com

CUANDO LLAMAR LA FUNCION escalar_a_humano (OBLIGATORIO si pasa)
- Cliente escribe "humano", "persona", "alguien real", "tu jefe", "el dueno"
- Detectas lenguaje agresivo o groserias
- Menciona: "demanda", "denuncia", "estafa", "fraude", "abogado", "tutela"
- Preguntas legales/contractuales
- Cliente pide negociar precio fuera del catalogo
- Pregunta por algo que NO esta en el catalogo de la KB
- Te pregunta sobre la competencia (no compares, escala)

Cuando llames a escalar_a_humano:
- motivo: una linea explicando por que escalas (ej: "cliente pide humano explicitamente", "mencion legal: abogado", "queja agresiva")
- urgencia: "alta" si hay mencion legal o lenguaje agresivo. "media" en los otros casos.

---

${input.kb_context}

---

Reglas finales:
- Responde SOLO con la respuesta al cliente, sin meta-comentarios.
- Cuando muestres un servicio del catalogo, menciona el precio si esta en la KB y un beneficio concreto.
- Si llamas escalar_a_humano, igual tu mensaje al cliente debe ser cordial: "Esto lo veo con un colega del equipo y te confirmo en un toque, en menos de 1 hora habil te respondemos".`;

const messages = [{ role: 'system', content: systemPrompt }];

if (Array.isArray(input.history) && input.history.length > 0) {
  input.history.forEach(h => {
    if (h.role && h.content) {
      messages.push({ role: h.role, content: h.content });
    }
  });
}

messages.push({ role: 'user', content: input.message });

// Definicion de tools (function calling)
const tools = [
  {
    type: 'function',
    function: {
      name: 'escalar_a_humano',
      description: 'Marca esta conversacion para que un humano del equipo intervenga. Usar cuando: cliente pide explicitamente humano, lenguaje agresivo, menciones legales (demanda/denuncia/abogado), negociacion de precio fuera de catalogo, contratos, preguntas que no se pueden responder desde la KB.',
      parameters: {
        type: 'object',
        properties: {
          motivo: {
            type: 'string',
            description: 'Razon corta de por que se escala (1 linea)'
          },
          urgencia: {
            type: 'string',
            enum: ['alta', 'media'],
            description: 'alta = atender YA (legal, agresivo). media = puede esperar 1-2 horas habiles.'
          }
        },
        required: ['motivo', 'urgencia']
      }
    }
  }
];

return {
  json: {
    messages,
    tools,
    contact_name: input.contact_name,
    contact_phone: input.contact_phone,
    conversacion_id: input.conversacion_id,
    rag_results: input.rag_results
  }
};

// Parsea respuesta de OpenAI (puede ser texto plano O tool call)
const openaiResp = $input.item.json;
const originalInput = $('Construir contexto KB').item.json;
const promptData = $('Construir prompt OpenAI').item.json;

const choice = openaiResp.choices?.[0];
const messageObj = choice?.message || {};
const finishReason = choice?.finish_reason || 'unknown';
const tokensUsed = openaiResp.usage?.total_tokens || 0;
const costEstimateUsd = (openaiResp.usage?.prompt_tokens || 0) * 0.0000025 + (openaiResp.usage?.completion_tokens || 0) * 0.00001;

let respuesta = '';
let toolCalled = null;
let toolArgs = null;

// Caso 1: el modelo llamo a una herramienta
if (finishReason === 'tool_calls' && Array.isArray(messageObj.tool_calls) && messageObj.tool_calls.length > 0) {
  const tc = messageObj.tool_calls[0];
  toolCalled = tc.function?.name || null;
  try {
    toolArgs = JSON.parse(tc.function?.arguments || '{}');
  } catch (e) {
    toolArgs = { raw: tc.function?.arguments };
  }

  // Para escalar_a_humano hardcodeamos respuesta amigable (evitamos round-trip extra)
  if (toolCalled === 'escalar_a_humano') {
    respuesta = 'Te derivo a un colega del equipo. Te respondemos en menos de 1 hora habil, gracias por la paciencia.';
  } else {
    respuesta = messageObj.content?.trim() || 'Listo, lo gestiono y te confirmo en un toque.';
  }
} else {
  // Caso 2: respuesta de texto normal
  respuesta = messageObj.content?.trim() || '';
}

if (!respuesta) {
  throw new Error(`OpenAI no devolvio respuesta utilizable. finish_reason=${finishReason}`);
}

return {
  json: {
    ok: true,
    respuesta,
    metadata: {
      contact_name: originalInput.contact_name,
      contact_phone: originalInput.contact_phone,
      conversacion_id: originalInput.conversacion_id,
      query_original: originalInput.message,
      servicios_consultados: (promptData.rag_results || []).map(r => ({ slug: r.slug, similarity: r.similarity })),
      tool_called: toolCalled,
      tool_args: toolArgs,
      needs_human_review: toolCalled === 'escalar_a_humano',
      tokens_used: tokensUsed,
      cost_estimate_usd: parseFloat(costEstimateUsd.toFixed(6)),
      finish_reason: finishReason
    }
  }
};
